void AXRNA_Init(void) {
    (void)lbl_eu_8051914C;
    if (axrna_refcount == 0) {
        memset(axrna_obj_pool, 0, 0xE40);
    }
    axrna_refcount++;
}

void AXRNA_Finish(void) {
    s32 i;
    if (--axrna_refcount == 0) {
        for (i = 0; i < 0x10; i++) {
            if ((s32)axrna_obj_pool[i].enable == 1) {
                AXRNA_Destroy(&axrna_obj_pool[i]);
            }
        }
        memset(axrna_obj_pool, 0, 0xE40);
    }
}

void axrna_voice_drop(void* voice) {
    u32* row;
    u32* w;
    s32 i, j;
    row = (u32*)axrna_obj_pool;
    for (i = 0; i < 0x10; i++) {
        w = row;
        for (j = 0; j < 2; j++) {
            if (voice == (void*)w[2]) {
                MIXReleaseChannel(axrna_obj_pool[i].voice[j]);
                axrna_obj_pool[i].voice[j] = NULL;
                return;
            }
            w++;
        }
        row += 0xE4 / 4;
    }
}

AXRNA_OBJ* AXRNA_Create(void* obj_arr, s32 maxnch, u8* buf) {
    AXRNA_OBJ* slot;
    void* sj;
    void* vpb;
    u32 j;
    u32 n;
    u8* bufp;
    u8* ch;
    u32 i;

    if (maxnch <= 0) {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0));
        return NULL;
    }
    if (obj_arr == NULL) {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x28));
        return NULL;
    }
    {
        void** walk = (void**)obj_arr;
        u32 k;
        for (k = 0; k < (u32)maxnch; k++) {
            if (*walk == 0) {
                RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x4e));
                return NULL;
            }
            walk++;
        }
    }

    {
        AXRNA_OBJ* q = axrna_obj_pool;
        u32 cnt = 0;
        for (n = 0; n < 2; n++) {
            for (j = 0; j < 8; j++) {
                if ((s8)q->enable != 0) {
                    q++;
                    cnt++;
                } else {
                    goto found_slot;
                }
            }
        }
    found_slot:
        if (cnt == 0x10) {
            RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x76));
            return NULL;
        }
        slot = &axrna_obj_pool[cnt];
    }
    slot->chanNum = (u8)maxnch;
    slot->numChan = (u8)maxnch;

    {
        /* the caller's journals are copied into the handle word by word: the
         * destination walks the handle from its base (+0x28) like retail */
        u32* d = (u32*)slot;
        void** s = (void**)obj_arr;
        u32 k;
        for (k = 0; k < (u32)slot->numChan;) {
            u32 v = (u32)*s;
            k++;
            d[0xa] = v;
            s++;
            d++;
        }
    }

    slot->vol = 0;
    slot->mixPanR = 0x7f;
    slot->mixAuxA = -0x3c0;
    slot->mixAuxB = -0x3c0;
    slot->mixPan = -0x3c0;
    slot->mixFader = 0;

    bufp = buf;
    ch = (u8*)slot;
    for (i = 0; i < slot->numChan; i++) {
        *(u32*)(ch + 0x10) = (u32)bufp;
        slot->bufSmpl = 0x1000;
        sj = SJRBF_Create(*(void**)(ch + 0x10), 0x2000, 0);
        *(u32*)(ch + 0x30) = (u32)sj;
        if (sj == NULL) {
            RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x97));
            AXRNA_Destroy(slot);
            return NULL;
        }
        vpb = AXAcquireVoice(0x1f, (void*)axrna_voice_drop, 0);
        *(u32*)(ch + 8) = (u32)vpb;
        if (vpb == NULL) {
            RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0xb2));
            AXRNA_Destroy(slot);
            return NULL;
        }
        GCRNA_LockCs();
        {
            void* v = *(void**)(ch + 8);
            if (v != 0) {
                MIXInitChannel(v, 3,
                               slot->vol, slot->mixAuxA, slot->mixAuxB, slot->mixPan,
                               0x40, slot->mixPanR, slot->mixFader);
            }
        }
        GCRNA_UnlockCs();
        bufp += 0x2000;
        ch += 4;
    }

    {
        u32 tbl;
        tbl = axrna_work_flags;
        if (slot != NULL) {
            slot->field_0x9c = (u16)tbl;
        }
        tbl = axrna_src_type;
        if (slot != NULL) {
            slot->srcType = tbl;
            slot->field_0x9e = 1;
        }
    }
    slot->field_0x9e = 0;
    AXRNA_SetSfreq(slot, 0xBB80);
    if (slot != NULL) {
        slot->bitPerSmpl = 0x10;
    }
    if (slot->numChan == 2) {
        if (slot != NULL) {
            if (slot->numChan > 0) {
                if (slot->pan[0] != -0xf) {
                    slot->pan[0] = -0xf;
                    GCRNA_LockCs();
                    if (slot->voice[0] != 0) {
MIXSetPan(slot->voice[0], (s32)axrna_pan_table[0]);
                    }
                    GCRNA_UnlockCs();
                }
            }
        }
        if (slot != NULL) {
            if (slot->numChan > 1) {
                if (slot->pan[1] != 0xf) {
                    slot->pan[1] = 0xf;
                    GCRNA_LockCs();
                    if (slot->voice[1] != 0) {
MIXSetPan(slot->voice[1], (s32)axrna_pan_table[0x1e]);
                    }
                    GCRNA_UnlockCs();
                }
            }
        }
    } else {
        if (slot != NULL) {
            if (slot->numChan > 0) {
                if (slot->pan[0] != 0) {
                    slot->pan[0] = 0;
                    GCRNA_LockCs();
                    if (slot->voice[0] != 0) {
MIXSetPan(slot->voice[0], (s32)axrna_pan_table[0xf]);
                    }
                    GCRNA_UnlockCs();
                }
            }
        }
    }
    slot->streamMode = 0;
    {
        s32 k;
        for (k = 0; k < 4; k++) {
            AXRNA_SetMain(slot, k, 0);
        }
    }
    criware_8039A8E0(slot, 0x10);
    slot->sw = 0;
    slot->enable = 1;
    return slot;
}

void AXRNA_Destroy(AXRNA_OBJ* self) {
    s32 i;
    if (self == NULL)
        return;
    AXRNA_SetPlaySw(self, 0);
    AXRNA_SetTransSw(self, 0);
    for (i = 0; i < self->numChan; i++) {
        void* sj = self->sjPlay[i];
        if (sj != NULL) {
            SJ_VT(sj)->destroy(sj);
        }
        GCRNA_LockCs();
        {
            void* v = self->voice[i];
            if (v != NULL) {
                MIXReleaseChannel(v);
                AXFreeVoice(self->voice[i]);
            }
        }
        GCRNA_UnlockCs();
    }
    memset(self, 0, 0xE4);
}

void AXRNA_SetTransSw(AXRNA_OBJ* self, s32 sw) {
    /* Declaration order drives MWCC callee-saved assignment (retail:
     * ch=r29, p38=r28, p48=r27, loop counter=r26). */
    u8* ch;
    SJ_CHUNK* p38;
    SJ_CHUNK* p48;
    s32 cur;
    s32 i, j, k;
    if (self == NULL)
        return;
    if (self == NULL) {
        cur = -1;
    } else {
        cur = (s32)(self->sw & 1);
    }
    if (sw == cur)
        return;
    if (sw == 1) {
        GCRNA_LockCs();
        ch = (u8*)self;
        p38 = &self->chunkB[0];
        p48 = &self->chunkA[0];
        for (i = 0; i < (s8)self->chanNum; i++) {
            void* sj = *(void**)(ch + 0x30);
            SJ_VT(sj)->reset(sj);
            memset(p38, 0, sizeof(*p38));
            memset(p48, 0, sizeof(*p48));
            if (self->streamMode == 1) {
                void* sj2 = *(void**)(ch + 0xc8);
                SJ_VT(sj2)->reset(sj2);
            }
            *(s32*)(ch + 0x58) = 0;
            ch += 4;
            p38++;
            p48++;
        }
        self->halfFeedPos = 0;
        self->feedTotal = 0;
        self->flashPos = 0;
        self->flashTotal = 0;
        self->playPos = -1;
        self->feedPos = 0;
        self->tsSkipCnt = 0;
        self->sw |= 1;
        GCRNA_UnlockCs();
    } else if (sw == 0) {
        for (i = 0; i < (s32)(s8)self->chanNum; i++) {
            s32 cnt = 0;
            for (j = 0; j < 0x14; j++) {
                for (k = 0; k < 0xa; k++) {
                    if (*(volatile s32*)((u8*)self + i * 4 + 0x58) == 0)
                        goto wait1;
                    cnt++;
                }
            }
        wait1:
            if (cnt == 0xc8) {
                RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0xd5));
                return;
            }
            cnt = 0;
            for (j = 0; j < 0x14; j++) {
                for (k = 0; k < 0xa; k++) {
                    if (*(volatile s32*)((u8*)self + i * 4 + 0x68) == 0)
                        goto wait2;
                    cnt++;
                }
            }
        wait2:
            if (cnt == 0xc8) {
                RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x10b));
                return;
            }
        }
        /* NB: bug-for-bug, retail masks with 2 (clears every other flag bit) */
        self->sw &= 2;
    } else {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x142));
    }
}

void AXRNA_SetPlaySw(AXRNA_OBJ* self, s32 sw) {
    /* Walking per-channel pointer (stride 4): voices at +8, buffer bases
     * at +0x10. Stop flag byte: bit1 = playing, bit0 = transferring.
     * NB: flag/fmt hold the hoisted AXPBADDR header words across the
     * AX calls (retail r30/r31); declaration order drives MWCC
     * callee-saved assignment. */
    u16 flag;
    u16 fmt;
    s32 cur;
    s32 i;
    u8* p;
    if (self == NULL)
        return;
    if (self == NULL) {
        cur = -1;
    } else {
        cur = (self->sw >> 1) & 1;
    }
    if (sw == cur)
        return;
    GCRNA_LockCs();
    if (sw == 1) {
        if (self->feedPos == 0 || self->feedPos > 0x800) {
            sw = 0;
        } else {
            sw = 0x800;
        }
        p = (u8*)self;
        i = 0;
        flag = 1;
        fmt = 0xa;
        for (; i < (s8)((u8*)self)[3]; i++) {
            if (*(void**)(p + 8) != NULL) {
                AXPBADDR addr;
                /* AX addresses split hi/lo around the 0x80000000 base */
                u32 mem = *(u32*)(p + 0x10);
                u32 loop = self->bufSmpl;
                u32 base = mem + 0x80000000u;
                u32 t = loop * 2;
                u32 endm = base + t - 2;
                u32 curad = base + sw;
                addr.loopFlag = flag;
                addr.format = fmt;
                addr.loopAddressHi = (u16)(base >> 17);
                addr.loopAddressLo = (u16)(base >> 15);
                addr.endAddressHi = (u16)(endm >> 17);
                addr.endAddressLo = (u16)(endm >> 15);
                addr.currentAddressHi = (u16)(curad >> 17);
                addr.currentAddressLo = (u16)(curad >> 15);
                AXSetVoiceAddr(*(void**)(p + 8), &addr);
                AXSetVoiceState(*(void**)(p + 8), flag);
            }
            p += 4;
        }
        self->sw |= 2;
    } else if (sw == 0) {
        p = (u8*)self;
        for (i = 0; i < (s8)((u8*)self)[3]; i++) {
            if (*(void**)(p + 8) != NULL)
                AXSetVoiceState(*(void**)(p + 8), 0);
            p += 4;
        }
        /* NB: bug-for-bug, retail masks with 1 (clears every other flag bit) */
        self->sw &= 1;
    } else {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x163));
    }
    GCRNA_UnlockCs();
}

s32 AXRNA_GetNumData(AXRNA_OBJ* self) {
    if (self == NULL)
        return -1;
    {
        void* p = self->sjPlay[self->chanNum - 1];
        struct SjObjVtbl *q = SJ_VT(p);
        /* Slot 9 in its 3-arg (avail) shape. */
        return 0x1000 - (s32)(((u32)((s32 (*)(void*, s32, void*))q->getAvail)(p, 0, q)) >> 1)
               - self->flashTotal;
    }
}

int AXRNA_GetNumRoom(AXRNA_OBJ* rna) {
    void *obj;
    if (rna == NULL) {
        return -1;
    }
    obj = rna->sjPlay[rna->chanNum - 1];
    return (unsigned int)SJ_VT(obj)->getAvail(obj, 0) >> 1;
}

void axrna_update_play(AXRNA_OBJ* self) {
    s32 i;
    s32 delta;
    s32 a4;
    void* voice;
    s32 cur;

    cur = self->playPos;
    voice = self->voice[self->chanNum - 1];
    if (voice == NULL)
        return;
    /* retail: (mem + 0x80000000) >> 1 -- addis/srwi pair */
    a4 = (s32)(*(u32*)((u8*)voice + 0xa2)
               - (((u32)self->buf[self->chanNum - 1] + 0x80000000u) >> 1));
    self->feedPos = a4;
    if (a4 < 0 || a4 > (s32)self->bufSmpl) {
        for (;;) {
        }
    }
    if (cur == -1) {
        if (a4 == 0) {
            delta = 0;
        } else {
            cur = 0;
            self->playPos = 0;
        }
    }
    if (cur != -1) {
        /* wrap-around delta: 0x1000 - (cur - a4), or plain a4 - cur when ahead */
        delta = 0x1000 - (cur - a4);
        if (a4 > cur) {
            delta = a4 - cur;
        }
    }
    delta = (delta / 0x800) * 0x800;
    if (delta > 0) {
        SJ_CHUNK out;
        s32 bytes = delta * 2;
        for (i = 0; i < self->chanNum; i++) {
            /* NB: keep the un-hoisted object load; hoisting it here shifts
             * register allocation on this function (baseline diff profile). */
            ((void(*)(void*, s32, s32, void*))((*(void***)self->sjPlay[i])[6]))(
                self->sjPlay[i], 1, bytes, &out);
            ((void(*)(void*, s32, void*))((*(void***)self->sjPlay[i])[8]))(
                self->sjPlay[i], 0, &out);
        }
        {
            s32 v = self->playPos + delta;
            self->playPos = v;
            if (v >= 0x1000) {
                self->playPos = v - 0x1000;
            }
        }
    }
    self->feedCount += delta;
}

void axrna_start_trans(AXRNA_OBJ* self) {
    /* Walkers per retail: the per-channel slots are parallel arrays, so the
     * staging chunks (stride 8) and the channel slots (stride 4) advance
     * separately. */
    s32 i;
    void* sj;
    void* obj;
    SJ_CHUNK chunkB;
    SJ_CHUNK chunkD;
    SJ_CHUNK chunkA;
    SJ_CHUNK chunkC;
    s32 size;

    for (i = 0; i < self->chanNum; i++) {
        if (self->voice[i] == 0)
            goto next;
        if (self->transBusy[i] != 0)
            goto next;
        sj = self->sjPlay[i];
        SJ_VT(sj)->getChunk(sj, 0, 0x2000, &chunkA);
        obj = self->sjIn[i];
        SJ_VT(obj)->getChunk(obj, 1, chunkA.size, &chunkB);
        /* signed truncating divide-by-32 round-down (srawi/addze in retail) */
        size = ((chunkB.size < chunkA.size) ? chunkB.size : chunkA.size) / 0x20
               * 0x20;
        SJ_SplitChunk(&chunkA, size, &chunkA, &chunkC);
        sj = self->sjPlay[i];
        SJ_VT(sj)->ungetChunk(sj, 0, &chunkC);
        SJ_SplitChunk(&chunkB, size, &chunkB, &chunkD);
        obj = self->sjIn[i];
        SJ_VT(obj)->ungetChunk(obj, 1, &chunkD);
        if (size == 0)
            return;
        self->chunkB[i] = chunkB;
        self->chunkA[i] = chunkA;
        /* logical shift right here (srwi in retail), unlike start_flash */
        self->halfFeedPos = (u32)size >> 1;
        DCFlushRange(self->chunkB[i].ptr, (u32)self->chunkB[i].size);
        self->transBusy[i] = 1;
        memcpy(chunkA.ptr, chunkB.ptr, size);
        DCFlushRange(chunkA.ptr, size);
        if (self->transBusy[i] == 1) {
            obj = self->sjIn[i];
            SJ_VT(obj)->putChunk(obj, 0, &self->chunkB[i]);
            obj = self->sjPlay[i];
            SJ_VT(obj)->putChunk(obj, 1, &self->chunkA[i]);
            self->transBusy[i] = 0;
            if (i == self->chanNum - 1) {
                self->feedTotal += self->halfFeedPos;
            }
        }
    next:
        ;
    }
}

/* Time Stretch feed: resamples input-ring data into the output rings, then
 * mirrors one chunk per channel from the output rings back into the
 * playback rings. NB (bug-for-bug): the availability probe reads sjIn[0] but
 * every actual chunk op walks the per-channel pointer chp, and the skip
 * counter only resets on a successful feed. */
void criware_80399F4C(AXRNA_OBJ* _this) {
    AXRNA_OBJ* chp;
    s32 dstx2;
    s32 srcx2;
    s32 i;
    s32 src_len;
    s32 dst_len;
    s32 m;
    s32 c4;
    SJ_CHUNK chunk2;
    SJ_CHUNK out;
    SJ_CHUNK split1;
    SJ_CHUNK chunk1;
    SJ_CHUNK split2;

    src_len = _this->tsSrcLen;
    dst_len = (src_len * _this->tsRatio / 100) & ~3;
    if (_this->chanNum > 1) {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x450));
        return;
    }

    chp = _this;
    dstx2 = dst_len * 2;
    srcx2 = src_len * 2;
    for (i = 0; i < _this->chanNum; i++) {
        /* NB: every SJ access reloads the object pointer from the slot,
         * matching retail (no caching across the opaque vtable calls). */
        if ((u32)SJ_VT(chp->sjTs[0])->getAvail(chp->sjTs[0], 0)
            < (u32)dstx2) {
            goto tail;
        }
        if ((u32)SJ_VT(_this->sjIn[0])->getAvail(_this->sjIn[0], 1)
            < (u32)srcx2) {
            c4 = _this->tsSkipCnt;
            if (c4 <= 2) {
                goto skip_inc;
            }
        }
        /* resample src_len input samples into a dst_len-sample chunk */
        SJ_VT(chp->sjTs[0])->getChunk(chp->sjTs[0], 0, dstx2, &chunk1);
        if ((u32)chunk1.size < (u32)dstx2) {
            RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x488));
            /* retail recomputes this slot from the base (+i*4), not chp */
            SJ_VT(_this->sjTs[i])->ungetChunk(_this->sjTs[i], 0, &chunk1);
            return;
        }
        SJ_VT(chp->sjIn[0])->getChunk(chp->sjIn[0], 1, srcx2, &chunk2);
        memcpy(axrna_chunk_pool, chunk2.ptr, chunk2.size);
        SJ_VT(chp->sjIn[0])->putChunk(chp->sjIn[0], 0, &chunk2);
        m = (u32)chunk2.size >> 1;
        if (m < src_len) {
            /* ring wrapped: pull the remainder, zero-fill any shortfall */
            SJ_VT(chp->sjIn[0])->getChunk(chp->sjIn[0], 1, (src_len - m) * 2,
                                          &chunk2);
            memcpy((char*)axrna_chunk_pool + m * 2, chunk2.ptr, chunk2.size);
            SJ_VT(chp->sjIn[0])->putChunk(chp->sjIn[0], 0, &chunk2);
            m += (u32)chunk2.size >> 1;
            if (m < src_len) {
                memset((char*)axrna_chunk_pool + m * 2, 0, (src_len - m) * 2);
            }
        }
        criware_8039B4E0((s16*)axrna_chunk_pool, src_len, (s16*)chunk1.ptr,
                         dst_len);
        SJ_VT(chp->sjTs[0])->putChunk(chp->sjTs[0], 1, &chunk1);
        _this->tsSkipCnt = 0;
        goto tail;
    skip_inc:
        _this->tsSkipCnt = c4 + 1;
    tail:
        /* mirror one aligned chunk from the output ring to the playback ring */
        SJ_VT(chp->sjPlay[0])->getChunk(chp->sjPlay[0], 0, 0x2000, &out);
        SJ_VT(chp->sjTs[0])->getChunk(chp->sjTs[0], 1, out.size, &chunk1);
        /* signed round-to-multiple-of-32 of the smaller chunk size */
        m = ((chunk1.size < out.size) ? chunk1.size : out.size) / 0x20 * 0x20;
        SJ_SplitChunk(&out, m, &out, &split1);
        SJ_VT(chp->sjPlay[0])->ungetChunk(chp->sjPlay[0], 0, &split1);
        SJ_SplitChunk(&chunk1, m, &chunk1, &split2);
        SJ_VT(chp->sjTs[0])->ungetChunk(chp->sjTs[0], 1, &split2);
        memcpy(out.ptr, chunk1.ptr, m);
        DCFlushRange(out.ptr, m);
        SJ_VT(chp->sjTs[0])->putChunk(chp->sjTs[0], 0, &chunk1);
        SJ_VT(chp->sjPlay[0])->putChunk(chp->sjPlay[0], 1, &out);
        _this->halfFeedPos = (u32)m >> 1;
        if (i == _this->chanNum - 1) {
            _this->feedTotal += (u32)m >> 1;
        }
        if (_this->feedTotal > 0xBB80) {
            axrna_sfreq++;
        }
        chp = (AXRNA_OBJ*)((char*)chp + 4);
    }
}

void axrna_start_flash(AXRNA_OBJ* self) {
    s32 i;
    s32 size;
    SJ_CHUNK out;
    SJ_CHUNK split;

    for (i = 0; i < self->chanNum; i++) {
        if (self->flashBusy[i] != 0)
            goto next;
        {
            void* sj = self->sjPlay[i];
            SJ_VT(sj)->getChunk(sj, 0, 0x2000, &out);
        }
        /* signed round-to-zero divide by 32 (srawi/addze in retail) */
        size = (out.size / 0x20) * 0x20;
        SJ_SplitChunk(&out, size, &out, &split);
        {
            void* sj = self->sjPlay[i];
            SJ_VT(sj)->ungetChunk(sj, 0, &split);
        }
        if (size == 0)
            return;
        self->chunkA[i] = out;
        self->flashPos = (s32)((u32)size >> 1);
        self->flashBusy[i] = 1;
        memset(out.ptr, 0, size);
        DCFlushRange(out.ptr, size);
        if (self->flashBusy[i] == 1) {
            void* obj;
            obj = self->sjPlay[i];
            SJ_VT(obj)->putChunk(obj, 1, &self->chunkA[i]);
            self->flashBusy[i] = 0;
            if (i == self->chanNum - 1) {
                self->flashTotal += self->flashPos;
            }
        }
    next:
        ;
    }
}

void AXRNA_ExecServer(void) {
    u32 i;
    AXRNA_OBJ* rna;
    s32 st;

    GCRNA_LockCs();
    for (i = 0; i < 0x10; i++) {
        rna = &axrna_obj_pool[i];
        if ((s32)rna->enable != 1)
            continue;
        if (rna == NULL)
            continue;
        if (rna == NULL) {
            st = -1;
        } else {
            st = ((rna->sw >> 1) & 1);
        }
        if (st == 1)
            axrna_update_play(rna);
        if (rna == NULL) {
            st = -1;
        } else {
            st = (rna->sw & 1);
        }
        if (st == 1) {
            if (rna->streamMode == 1)
                criware_80399F4C(rna);
            else
                axrna_start_trans(rna);
        } else {
            if (rna == NULL) {
                st = -1;
            } else {
                st = ((rna->sw >> 1) & 1);
            }
            if (st == 1 && rna->flashTotal < (s32)rna->bufSmpl)
                axrna_start_flash(rna);
        }
    }
    GCRNA_UnlockCs();
}

void AXRNA_SetNumChan(AXRNA_OBJ* self, u8 numChan) {
    if (self != NULL) {
        self->chanNum = numChan;
    }
}

void AXRNA_SetSfreq(AXRNA_OBJ* self, s32 sfreq) {
    u8* p;
    s32 hi;
    u16 lo;
    s32 i;
    AXPBSRC src;
    if (self == NULL)
        return;
    if (sfreq == 0x7d1c) {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x4b5));
    }
    self->sfreq = sfreq;
    /* AX SRC ratio: integer part = rate/32000 (magic 0x10624dd3, shift 11);
     * fraction part computed as (rate<<8)/125 (same magic, shift 3). */
    hi = sfreq / 32000;
    lo = (sfreq << 8) / 125;
    p = (u8*)self;
    /* NB: reuse sfreq as the channel-loop counter so MWCC recycles its
     * register (retail: li r26, 0 over the dead parameter). */
    for (i = 0; i < self->numChan; i++) {
        GCRNA_LockCs();
        {
            void* e = *(void**)(p + 8);
            if (e != NULL) {
                src.ratioHi = (u16)hi;
                src.ratioLo = lo;
                src.currentAddressFrac = 0;
                src.last_samples[0] = 0;
                src.last_samples[1] = 0;
                src.last_samples[2] = 0;
                src.last_samples[3] = 0;
                AXSetVoiceSrcType(e, self->srcType);
                /* reload: AXSetVoiceSrcType may have changed the slot */
                AXSetVoiceSrc(*(void**)(p + 8), &src);
            }
        }
        GCRNA_UnlockCs();
        p += 4;
    }
}

void AXRNA_SetOutVol(AXRNA_OBJ* self, s32 vol) {
    s32 t;
    s32 v;
    s32 i;
    if (self == NULL)
        return;
    t = vol & (vol >> 31);
    v = -960;
    if (t > -960)
        v = t;
    if (v == self->vol)
        return;
    self->vol = v;
    for (i = 0; i < self->numChan; i++) {
        GCRNA_LockCs();
        if (self->voice[i] != NULL)
            MIXSetInput(self->voice[i], v);
        GCRNA_UnlockCs();
    }
}

void AXRNA_SetOutPan(AXRNA_OBJ* self, s32 index, s32 pan) {
    s32 p;
    s32 v;
    if (self == NULL)
        return;
    if (index >= self->numChan)
        return;
    /* clamp pan into [-15, 15] */
    p = (pan < 0xf) ? pan : 0xf;
    v = (p > -0xf) ? p : -0xf;
    if (self->pan[index] == v)
        return;
    self->pan[index] = v;
    GCRNA_LockCs();
    {
        void* e = self->voice[index];
        if (e != NULL) {
            MIXSetPan(e, (s32)axrna_pan_table[v + 0xf]);
        }
    }
    GCRNA_UnlockCs();
}

void AXRNA_SetBitPerSmpl(AXRNA_OBJ* self, u32 val) {
    if (self != NULL) {
        self->bitPerSmpl = val;
    }
}

int AXRNA_SetStmHdInfo(void) { return 0x0; }

int AXRNA_DiscardData(void) { return 0x0; }

void AXRNA_SetMain(void* self, u32 index, s32 val) {
    s32* p;
    s32 t;
    s32 v;
    u8* q;
    s32 i;
    if (self == NULL)
        return;
    if (index > 3) {
        RNAERR_CallErrFunc((const char*)(lbl_eu_80519150 + 0x4e4));
        return;
    }
    t = val & (val >> 31);
    v = -960;
    if (t > -960)
        v = t;
    p = (s32*)((u8*)self + index * 4);
    if (v == p[0xd0 / 4])
        return;
    p[0xd0 / 4] = v;
    {
        q = (u8*)self;
        for (i = 0; i < (s8)((u8*)self)[2]; i++) {
            GCRNA_LockCs();
            {
                void* e = *(void**)(q + 8);
                if (e != NULL)
                    MIXRmtSetFader(e, index, p[0xd0 / 4]);
            }
            GCRNA_UnlockCs();
            q += 4;
        }
    }
}

/* Per-channel remote (controller) volume update. NOTE (bug-for-bug):
 * retail gates the 0xd4 tap with flag bit 2 and the 0xd8 tap with bit 1
 * (crossed versus the natural bit order). */
void criware_8039A8E0(AXRNA_OBJ* self, u32 flags) {
    s32 vol;
    u32 b4;
    u32 b0;
    u32 b1;
    u32 b2;
    u32 b3;
    u32 msk;
    s32 i;
    s32 fader0;
    s32 fader1;
    s32 fader2;
    s32 fader3;

    fader0 = -0x3c0;
    fader1 = -0x3c0;
    fader2 = -0x3c0;
    fader3 = -0x3c0;
    if (self == NULL)
        return;
    self->rmtSw = (u8)(flags & 0x1f);
    i = 0;
    b4 = flags & 0x10;
    b0 = flags & 1;
    b1 = flags & 2;
    b2 = flags & 4;
    b3 = flags & 8;
    msk = flags & 0xf;
    vol = -0x3c0;
    while (i < self->numChan) {
        GCRNA_LockCs();
        if (self->voice[i] != NULL) {
            if (b4) {
                MIXSetFader(self->voice[i], self->mixFader);
            } else {
                MIXSetFader(self->voice[i], -0x3c0);
            }
            if (b0)
                fader0 = self->fader[0];
            if (b1)
                fader1 = self->fader[1];
            if (b2)
                fader2 = self->fader[2];
            if (b3)
                fader3 = self->fader[3];
            if (msk) {
                MIXRmtSetVolumes(self->voice[i], 0, fader0,
                                 fader1, fader2, fader3, vol, vol, vol, vol);
                AXSetVoiceRmtOn(self->voice[i], 1);
            } else {
                AXSetVoiceRmtOn(self->voice[i], 0);
            }
        }
        GCRNA_UnlockCs();
        i++;
    }
}

/* .bss: definitions after the code, reverse retail order for MWCC emission. */
u32 axrna_chunk_pool;
u32 axrna_sfreq;
AXRNA_OBJ axrna_obj_pool[0x10];
u32 axrna_work_flags;
u32 axrna_refcount;
